import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { int n = Integer.parseInt(br.readLine()); char[] s = br.readLine().toCharArray(); List<int[]> ops = new ArrayList<>(); int currentFlip = 0; for (int i = n - 2; i >= 0; i--) { if (((s[i] - '0') ^ currentFlip) == 1 && ((s[i + 1] - '0') ^ currentFlip) == 0) { ops.add(new int[]{1, i + 1}); currentFlip ^= 1; } } out.println(ops.size()); for (int[] op : ops) { out.println(op[0] + " " + op[1]); } } out.flush(); out.close(); } }